.ccard{background:rgba(255,255,255,0.88);border:1px solid rgba(15,23,42,0.07);border-radius:14px;padding:20px 24px;transition:all 0.28s cubic-bezier(0.22,1,0.36,1);cursor:pointer;box-shadow:0 1px 3px rgba(15,23,42,0.03)}
.ccard:hover{border-color:rgba(91,95,239,0.32);background:#fff;transform:translateX(5px);box-shadow:-4px 0 0 #5B5FEF,0 6px 24px rgba(91,95,239,0.09)}

input,textarea,select{background:rgba(255,255,255,0.9);border:1px solid rgba(15,23,42,0.1);border-radius:10px;color:#0F172A;padding:11px 15px;font-family:'Inter',sans-serif;font-size:14px;width:100%;outline:none;transition:all 0.22s ease}
