import React, { useState, useEffect, useRef } from "react";

/* ── Brand SVG Icons ─────────────────────────────────────── */
const D365Icon = () => (
  <svg viewBox="0 0 48 48" width="32" height="32" fill="none" xmlns="http://www.w3.org/2000/svg">
    <rect width="48" height="48" rx="8" fill="#0078D4"/>
    <path d="M24 8C15.163 8 8 15.163 8 24s7.163 16 16 16 16-7.163 16-16S32.837 8 24 8zm0 4c6.617 0 12 5.383 12 12s-5.383 12-12 12S12 30.617 12 24 17.383 12 24 12z" fill="white" opacity="0.3"/>
    <path d="M24 14c-5.523 0-10 4.477-10 10s4.477 10 10 10 10-4.477 10-10-4.477-10-10-10zm-2 14.5v-9l7 4.5-7 4.5z" fill="white"/>
  </svg>
);

const PowerPlatformIcon = () => (
  <svg viewBox="0 0 48 48" width="32" height="32" fill="none" xmlns="http://www.w3.org/2000/svg">
    <rect width="48" height="48" rx="8" fill="#742774"/>
    <path d="M10 24L24 10l14 14-14 14L10 24z" fill="#C55FA3" opacity="0.6"/>
    <path d="M18 24l6-6 6 6-6 6-6-6z" fill="white"/>
    <rect x="22" y="8" width="4" height="8" rx="2" fill="#E3A9E0"/>
    <rect x="22" y="32" width="4" height="8" rx="2" fill="#E3A9E0"/>
    <rect x="8" y="22" width="8" height="4" rx="2" fill="#E3A9E0"/>
    <rect x="32" y="22" width="8" height="4" rx="2" fill="#E3A9E0"/>
  </svg>
);

const ReactIcon = () => (
  <svg viewBox="0 0 48 48" width="32" height="32" xmlns="http://www.w3.org/2000/svg">
    <rect width="48" height="48" rx="8" fill="#1A1A2E"/>
    <g transform="translate(24,24)">
      <ellipse rx="12" ry="4.5" fill="none" stroke="#61DAFB" strokeWidth="1.8"/>
      <ellipse rx="12" ry="4.5" fill="none" stroke="#61DAFB" strokeWidth="1.8" transform="rotate(60)"/>
      <ellipse rx="12" ry="4.5" fill="none" stroke="#61DAFB" strokeWidth="1.8" transform="rotate(120)"/>
      <circle r="2.5" fill="#61DAFB"/>
    </g>
  </svg>
);

const NodeIcon = () => (
  <svg viewBox="0 0 48 48" width="32" height="32" xmlns="http://www.w3.org/2000/svg">
    <rect width="48" height="48" rx="8" fill="#1B3A2D"/>
    <path d="M24 9l13 7.5v15L24 39 11 31.5v-15L24 9z" fill="none" stroke="#339933" strokeWidth="1.5"/>
    <path d="M24 13l9.5 5.5v11L24 35l-9.5-5.5v-11L24 13z" fill="#339933" opacity="0.2"/>
    <text x="24" y="28" textAnchor="middle" fill="#339933" fontSize="11" fontFamily="Arial" fontWeight="bold">JS</text>
  </svg>
);

const AzureIcon = () => (
  <svg viewBox="0 0 48 48" width="32" height="32" fill="none" xmlns="http://www.w3.org/2000/svg">
    <rect width="48" height="48" rx="8" fill="#0078D4"/>
    <path d="M18 10h8l-10 20h8L12 38l18-3-8-5 8-20z" fill="white"/>
  </svg>
);

const CRMIcon = () => (
  <svg viewBox="0 0 48 48" width="32" height="32" fill="none" xmlns="http://www.w3.org/2000/svg">
    <rect width="48" height="48" rx="8" fill="#EC4899"/>
    <rect x="10" y="14" width="28" height="20" rx="3" fill="none" stroke="white" strokeWidth="2"/>
    <circle cx="24" cy="22" r="4" fill="white" opacity="0.9"/>
    <path d="M16 34c0-4 3.6-7 8-7s8 3 8 7" stroke="white" strokeWidth="2" strokeLinecap="round" fill="none" opacity="0.9"/>
    <circle cx="34" cy="16" r="3" fill="#FDE68A"/>
    <path d="M32 16h4M34 14v4" stroke="#F59E0B" strokeWidth="1.5" strokeLinecap="round"/>
  </svg>
);

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&family=Inter:wght@400;500;600&display=swap');
* { margin: 0; padding: 0; box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { font-family: 'Inter', 'Segoe UI', sans-serif; background: #FAFBFF; color: #0F172A; overflow-x: hidden; }
.df { font-family: 'Sora', 'Segoe UI', sans-serif; }
.gt { background: linear-gradient(135deg, #1B1F3B 0%, #5B5FEF 55%, #00B8D9 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.gc { background: linear-gradient(135deg, #5B5FEF, #00D4FF); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }

.glass {
  background: rgba(255,255,255,0.8);
  border: 1px solid rgba(15,23,42,0.07);
  border-radius: 18px;
  transition: transform 0.32s cubic-bezier(0.22,1,0.36,1), box-shadow 0.32s ease, border-color 0.32s ease;
  box-shadow: 0 1px 3px rgba(15,23,42,0.04), 0 6px 24px rgba(15,23,42,0.05);
  position: relative; overflow: hidden;
}
.glass::before {
  content: ''; position: absolute; inset: 0; border-radius: 18px;
  background: linear-gradient(135deg, rgba(91,95,239,0.04), rgba(0,212,255,0.02));
  opacity: 0; transition: opacity 0.32s; pointer-events: none;
}
.glass:hover { transform: translateY(-5px); border-color: rgba(91,95,239,0.28); box-shadow: 0 16px 48px rgba(91,95,239,0.13); background: rgba(255,255,255,0.96); }
.glass:hover::before { opacity: 1; }

.gs { background: rgba(255,255,255,0.92); border: 1px solid rgba(15,23,42,0.07); border-radius: 18px; box-shadow: 0 1px 3px rgba(15,23,42,0.04), 0 6px 24px rgba(15,23,42,0.04); }

.btn-p { background: linear-gradient(135deg,#4F53E8,#00C4F0); border: none; color: #fff; padding: 11px 24px; border-radius: 50px; font-family: 'Sora','Segoe UI',sans-serif; font-weight: 600; font-size: 14px; cursor: pointer; transition: all 0.28s cubic-bezier(0.22,1,0.36,1); box-shadow: 0 4px 14px rgba(79,83,232,0.24); letter-spacing: 0.01em; }
.btn-p:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(79,83,232,0.36); }
.btn-o { background: transparent; border: 1px solid rgba(15,23,42,0.15); color: #0F172A; padding: 11px 24px; border-radius: 50px; font-family: 'Sora','Segoe UI',sans-serif; font-weight: 500; font-size: 14px; cursor: pointer; transition: all 0.28s cubic-bezier(0.22,1,0.36,1); }
.btn-o:hover { border-color: #5B5FEF; background: rgba(91,95,239,0.07); transform: translateY(-2px); }

.orb { position: absolute; border-radius: 50%; filter: blur(100px); opacity: 0.17; pointer-events: none; }
@keyframes fl1 { 0%,100%{transform:translate(0,0) scale(1)} 40%{transform:translate(28px,-22px) scale(1.05)} 70%{transform:translate(-12px,18px) scale(0.96)} }
@keyframes fl2 { 0%,100%{transform:translate(0,0) scale(1)} 35%{transform:translate(-26px,26px) scale(1.07)} 70%{transform:translate(26px,-14px) scale(0.94)} }
@keyframes fl3 { 0%,100%{transform:translate(0,0) scale(1)} 50%{transform:translate(18px,22px) scale(1.08)} }
.o1{animation:fl1 14s ease-in-out infinite} .o2{animation:fl2 18s ease-in-out infinite} .o3{animation:fl3 12s ease-in-out infinite}

@keyframes fadeUp { from{opacity:0;transform:translateY(28px)} to{opacity:1;transform:translateY(0)} }
@keyframes scaleIn { from{opacity:0;transform:scale(0.95) translateY(14px)} to{opacity:1;transform:scale(1) translateY(0)} }
.reveal{opacity:0} .reveal.visible{animation:fadeUp 0.65s cubic-bezier(0.22,1,0.36,1) forwards}
.reveal-scale{opacity:0} .reveal-scale.visible{animation:scaleIn 0.6s cubic-bezier(0.22,1,0.36,1) forwards}
.reveal-d1.visible{animation-delay:0.07s} .reveal-d2.visible{animation-delay:0.14s} .reveal-d3.visible{animation-delay:0.21s}
.reveal-d4.visible{animation-delay:0.28s} .reveal-d5.visible{animation-delay:0.35s} .reveal-d6.visible{animation-delay:0.42s}

@keyframes heroFade{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:translateY(0)}}
.h1{animation:heroFade 0.85s 0.1s cubic-bezier(0.22,1,0.36,1) forwards;opacity:0}
.h2{animation:heroFade 0.85s 0.22s cubic-bezier(0.22,1,0.36,1) forwards;opacity:0}
.h3{animation:heroFade 0.85s 0.34s cubic-bezier(0.22,1,0.36,1) forwards;opacity:0}
.h4{animation:heroFade 0.85s 0.46s cubic-bezier(0.22,1,0.36,1) forwards;opacity:0}

.nl{color:#64748B;font-family:'Inter',sans-serif;font-size:14px;font-weight:500;cursor:pointer;transition:color 0.2s;position:relative}
.nl:hover,.nl.act{color:#0F172A}
.nl::after{content:'';position:absolute;bottom:-4px;left:0;width:0;height:2px;background:linear-gradient(90deg,#5B5FEF,#00D4FF);transition:width 0.3s;border-radius:2px}
.nl:hover::after,.nl.act::after{width:100%}

.tag{padding:3px 11px;background:rgba(15,23,42,0.04);border:1px solid rgba(15,23,42,0.07);border-radius:50px;font-size:12px;color:#64748B}
.taga{padding:4px 12px;background:rgba(91,95,239,0.08);border:1px solid rgba(91,95,239,0.18);border-radius:50px;font-size:12px;color:#4347C4;font-family:'Sora',sans-serif}

.ccard{background:rgba(255,255,255,0.88);border:1px solid rgba(15,23,42,0.07);border-radius:14px;padding:20px 24px;transition:all 0.28s cubic-bezier(0.22,1,0.36,1);cursor:pointer;box-shadow:0 1px 3px rgba(15,23,42,0.03)}
.ccard:hover{border-color:rgba(91,95,239,0.32);background:#fff;transform:translateX(5px);box-shadow:-4px 0 0 #5B5FEF,0 6px 24px rgba(91,95,239,0.09)}

input,textarea,select{background:rgba(255,255,255,0.9);border:1px solid rgba(15,23,42,0.1);border-radius:10px;color:#0F172A;padding:11px 15px;font-family:'Inter',sans-serif;font-size:14px;width:100%;outline:none;transition:all 0.22s ease}
input:focus,textarea:focus,select:focus{border-color:#5B5FEF;box-shadow:0 0 0 3px rgba(91,95,239,0.09)}
input::placeholder,textarea::placeholder{color:#94A3B8}
select option{background:#FFF;color:#0F172A}

::-webkit-scrollbar{width:4px} ::-webkit-scrollbar-track{background:#FAFBFF} ::-webkit-scrollbar-thumb{background:rgba(91,95,239,0.32);border-radius:3px}

.sn{font-family:'Sora',sans-serif;font-size:40px;font-weight:800;background:linear-gradient(135deg,#1B1F3B,#5B5FEF 50%,#00B8D9);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;letter-spacing:-1.5px}
.icon-box{transition:transform 0.28s cubic-bezier(0.22,1,0.36,1)}
.glass:hover .icon-box{transform:scale(1.1) rotate(-2deg)}
.divider{height:1px;background:linear-gradient(90deg,transparent,rgba(15,23,42,0.07),transparent)}
.sec-sub{color:#64748B;line-height:1.72}

.ham{display:none}
@media(max-width:900px){
  .r3{grid-template-columns:1fr 1fr !important} .r4{grid-template-columns:1fr 1fr !important}
  .r2{grid-template-columns:1fr !important} .hh{font-size:40px !important;letter-spacing:-1.5px !important}
  .ph{font-size:40px !important} .mh{display:none !important} .fg{grid-template-columns:1fr 1fr !important}
  .ham{display:block !important}
}
@media(max-width:600px){
  .r3{grid-template-columns:1fr !important} .r4{grid-template-columns:1fr !important}
  .sg{grid-template-columns:1fr 1fr !important} .hh{font-size:32px !important}
}
`;

function useReveal() {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { el.classList.add("visible"); obs.disconnect(); } },
      { threshold: 0.1 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return ref;
}

/* ── Data ─────────────────────────────────────────────────── */
const SERVICES = [
  {
    IconComp: D365Icon, title: "Microsoft D365 CRM", sub: "Dynamics 365 Solutions",
    color: "#0078D4", bg: "rgba(0,120,212,0.08)", bd: "rgba(0,120,212,0.25)",
    desc: "Unlock the full potential of Microsoft Dynamics 365 CRM to transform sales, service, and marketing operations with seamless integrations and deep customization.",
    features: ["Sales Automation","Customer Insights","Custom Entities","Third-party Integrations","Field Service","Marketing Automation"]
  },
  {
    IconComp: PowerPlatformIcon, title: "Power Platform", sub: "Low-Code Innovation",
    color: "#742774", bg: "rgba(116,39,116,0.08)", bd: "rgba(116,39,116,0.25)",
    desc: "Build powerful business apps, automate complex workflows, and derive actionable insights using Power Apps, Power Automate, Power BI, and Power Virtual Agents.",
    features: ["Power Apps","Power Automate","Power BI Dashboards","Virtual Agents","Dataverse","ALM & DevOps"]
  },
  {
    IconComp: AzureIcon, title: "Azure Services", sub: "Cloud Infrastructure",
    color: "#0078D4", bg: "rgba(0,120,212,0.08)", bd: "rgba(0,120,212,0.25)",
    desc: "Design, deploy, and manage enterprise-grade cloud solutions on Microsoft Azure — from infrastructure and security to AI services, DevOps pipelines, and serverless compute.",
    features: ["Azure DevOps","Cloud Architecture","App Services","AI & Cognitive","Azure AD","Cost Optimization"]
  },
  {
    IconComp: ReactIcon, title: "React & React Native", sub: "Web & Mobile Apps",
    color: "#61DAFB", bg: "rgba(97,218,251,0.09)", bd: "rgba(97,218,251,0.28)",
    desc: "We craft high-performance web and mobile applications using React and React Native — delivering seamless cross-platform user experiences that delight.",
    features: ["Single-Page Apps","iOS & Android","Component Libraries","Performance Tuning","State Management","CI/CD Pipelines"]
  },
  {
    IconComp: NodeIcon, title: "Node.js Backend", sub: "Scalable APIs & Services",
    color: "#339933", bg: "rgba(51,153,51,0.09)", bd: "rgba(51,153,51,0.28)",
    desc: "Build fast, scalable, and reliable server-side applications and REST/GraphQL APIs with Node.js — from microservices to real-time platforms.",
    features: ["REST & GraphQL APIs","Microservices","WebSocket Systems","Cloud Deployment","Database Design","Auth & Security"]
  },
  {
    IconComp: CRMIcon, title: "Custom CRM Software", sub: "Business-First Solutions",
    color: "#EC4899", bg: "rgba(236,72,153,0.09)", bd: "rgba(236,72,153,0.28)",
    desc: "We design and develop tailor-made CRM systems built around your exact business workflows — giving you complete ownership, flexibility, and long-term value.",
    features: ["Bespoke Architecture","Pipeline Management","Reporting & Analytics","Workflow Automation","Role-based Access","Mobile-Ready"]
  },
];

const TEAM = [
  { name: "Alex Morgan", role: "CEO & Founder", init: "AM", c: "#5B5FEF" },
  { name: "Priya Sharma", role: "Chief Technology Officer", init: "PS", c: "#0078D4" },
  { name: "Jordan Lee", role: "Head of D365 Practice", init: "JL", c: "#742774" },
  { name: "Sara Chen", role: "Lead React Engineer", init: "SC", c: "#61DAFB" },
  { name: "Marcus Webb", role: "Power Platform Architect", init: "MW", c: "#742774" },
  { name: "Aisha Okonkwo", role: "Head of Delivery", init: "AO", c: "#FB923C" },
  { name: "Ravi Patel", role: "Node.js Tech Lead", init: "RP", c: "#339933" },
  { name: "Lucia Ferreira", role: "UX Design Lead", init: "LF", c: "#EC4899" },
];

const JOBS = [
  { title: "Senior D365 CRM Developer", type: "Full-time", loc: "Remote / Hybrid", dept: "Microsoft Practice" },
  { title: "Power Platform Consultant", type: "Full-time", loc: "Remote", dept: "Microsoft Practice" },
  { title: "Azure Cloud Architect", type: "Full-time", loc: "Remote", dept: "Cloud Practice" },
  { title: "React Native Developer", type: "Full-time", loc: "Remote", dept: "Engineering" },
  { title: "Node.js Backend Engineer", type: "Full-time", loc: "Remote / Hybrid", dept: "Engineering" },
  { title: "Business Analyst – CRM", type: "Full-time", loc: "On-site", dept: "Consulting" },
  { title: "Power BI Developer", type: "Full-time", loc: "Remote", dept: "Microsoft Practice" },
  { title: "DevOps Engineer", type: "Full-time", loc: "Remote", dept: "Engineering" },
];

/* ── Navbar ────────────────────────────────────────────── */
function Navbar({ page, nav }) {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  useEffect(() => {
    const fn = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", fn);
    return () => window.removeEventListener("scroll", fn);
  }, []);
  const go = (p) => { nav(p); setOpen(false); };
  const navLinks = ["Home","Services","About","Careers","Contact"];
  return (
    <nav style={{ position:"fixed",top:0,left:0,right:0,zIndex:200,padding:"0 36px",height:64,display:"flex",alignItems:"center",justifyContent:"space-between",background:scrolled?"rgba(250,251,255,0.9)":"transparent",backdropFilter:scrolled?"blur(24px)":"none",WebkitBackdropFilter:scrolled?"blur(24px)":"none",borderBottom:scrolled?"1px solid rgba(15,23,42,0.06)":"none",boxShadow:scrolled?"0 2px 16px rgba(15,23,42,0.05)":"none",transition:"all 0.3s ease" }}>
      <div onClick={() => go("Home")} style={{ cursor:"pointer",display:"flex",alignItems:"center",gap:9 }}>
        <div style={{ width:32,height:32,borderRadius:8,background:"linear-gradient(135deg,#5B5FEF,#00C4F0)",display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Sora',sans-serif",fontWeight:800,fontSize:15,color:"#fff",boxShadow:"0 4px 10px rgba(91,95,239,0.3)" }}>E</div>
        <span className="df" style={{ fontSize:17,fontWeight:700,color:"#0F172A",letterSpacing:"-0.3px" }}>Elevvo Technologies</span>
      </div>
      <div className="mh" style={{ display:"flex",gap:32,alignItems:"center" }}>
        {navLinks.map(l => <span key={l} className={"nl"+(page===l?" act":"")} onClick={() => go(l)}>{l}</span>)}
      </div>
      <button className="btn-p mh" style={{ padding:"8px 20px",fontSize:13 }} onClick={() => go("Contact")}>Get in Touch</button>
      <button onClick={() => setOpen(!open)} className="ham" style={{ background:"none",border:"1px solid rgba(15,23,42,0.13)",borderRadius:7,color:"#0F172A",fontSize:17,cursor:"pointer",padding:"5px 10px" }}>☰</button>
      {open && (
        <div style={{ position:"absolute",top:64,left:0,right:0,background:"rgba(250,251,255,0.97)",backdropFilter:"blur(20px)",borderBottom:"1px solid rgba(15,23,42,0.07)",padding:"20px 36px",display:"flex",flexDirection:"column",gap:18,zIndex:300 }}>
          {navLinks.map(l => <span key={l} className={"nl"+(page===l?" act":"")} style={{ fontSize:16 }} onClick={() => go(l)}>{l}</span>)}
        </div>
      )}
    </nav>
  );
}

/* ── Hero ──────────────────────────────────────────────── */
function Hero({ nav }) {
  return (
    <section style={{ minHeight:"88vh",display:"flex",alignItems:"center",position:"relative",overflow:"hidden",padding:"100px 36px 56px" }}>
      <div className="orb o1" style={{ width:640,height:640,background:"#5B5FEF",top:"-140px",right:"-160px" }} />
      <div className="orb o2" style={{ width:400,height:400,background:"#00C4F0",bottom:"-50px",left:"-70px" }} />
      <div className="orb o3" style={{ width:260,height:260,background:"#7B7FF5",top:"40%",left:"44%" }} />
      <div style={{ position:"absolute",inset:0,backgroundImage:"radial-gradient(circle,rgba(15,23,42,0.045) 1px,transparent 1px)",backgroundSize:"32px 32px",pointerEvents:"none",opacity:0.55 }} />
      <div style={{ maxWidth:1200,margin:"0 auto",width:"100%",position:"relative",zIndex:1 }}>
        <div style={{ maxWidth:820 }}>
          <h1 className="df h1 hh" style={{ fontSize:76,fontWeight:800,lineHeight:1.03,letterSpacing:"-3px",marginBottom:20 }}>
            We Build Systems<br /><span className="gt">That Scale With You</span>
