          </div>
          {cols.map(col => (
            <div key={col.t}>
              <h4 className="df" style={{ fontSize:10,fontWeight:700,marginBottom:16,textTransform:"uppercase",letterSpacing:"1.2px",color:"#0F172A" }}>{col.t}</h4>
              <div style={{ display:"flex",flexDirection:"column",gap:10 }}>
